local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[406703]=b({e[24044],406703,6,70,330,"「律回り歳晩れて氷霜少なし、春人間に到らば草木知る……そなた、このセイランと共に、庭歩きに興じてくれぬか？」",200067,2,"deco/character/406703",false,false,1,false,false,false,false,"1",false,"140,0,0.98","0,0,0.98",false,"0,0,0.98","0,0,0.98","0,0,0.98",0,1,5520,5000,2974,4677,8000,8500,16000,8000,15000,8000,8000,"qingluan_cj"},h)g[406704]=b({e[17044],406704,2,81,331,"「清冽なる水は身の穢れを祓うが、其の内の卑俗なる欲を洗い流すには至らぬ。\n……そなたが関心を抱いておるのなら、我は構わぬぞ。共に暑気を払うとしよう。」",200067,2,"deco/character/qingluan_xr",false,false,false,false,false,false,false,"",0,1,2686,5000,1327,2513,4000,8000,8000,8000,18867,8000,8000,"qingluan_xr"},h)g[406801]=b({e[17023],406801,false,146,332,false,200068,false,"deco/character/ruyuecaiyin",302002,60,1,false,false,false,10,"0.98","50,130,1","0,0,0.98","0,0,0.98","0,0,0.98","0,0,0.98","0,0,0.98","-20,0,0.98","20,0,0.98","0,0,0.98",false,false,1864,871,386,1272,798,1609,2584,1272,798,1609,1026},h)g[406802]=b({e[12034],406802,1,4,333,"「今夜の読み聞かせは、『眠り姫』の話にしよっか。\n……ん？ これは、子供のおとぎ話じゃなくて、愛と勇気の物語なの。\n王子のように、茨の道を切り開いて愛する人に会いにいくような、勇敢な人になってもらわないと……。\nえ、先生は何になるの、って？\nふふっ、先生は、王子様を待つお姫様になるわ。\nあんまり長く待たせちゃイ・ヤ・よ♡」",200068,1,"deco/character/ruyuecaiyin_0",302002,60,1,1896,852,392,1189,796,2043,2247,1189,796,2043,1012},h)g[406803]=b({e[21034],406803,4,74,334,"「今日は一日先生のために時間をくれるって言ったのに……。うちの学校だと、授業中にスマホを触った生徒は廊下に立たされるらしいのよね。う～ん、あなたへの罰は何にし・よ・う・か・な～？」",200068,2,"deco/character/406803",false,false,false,false,false,false,false,"1",false,false,false,"0,-100,1",1849,871,398,1073,728,2201,2363,1073,728,2201,1102,1,3319,5000,1614,3031,3333,10000,10000,10000,13000,8000,3333},h)g[406804]=b({e[24034],406804,5,116,335,"「どう？　素敵でしょ、この晴れ着。けど、どうしても動きにくいわね……。ねえ、私を起こしてもらえる？　それとも、一緒に寝ころびたい？」",200068,2,"deco/character/ruyuecaiyin_YD",false,false,false,false,1,false,false,"1",false,"0,120,0.95","-250,120,0.95","240,-140,0.89","-250,120,0.95","-250,120,0.95","-60,60,0.95",2255,1049,398,553,28,2979,3356,592,747,2901,false,1,1489,5000,733,1293,5333,10000,7500,8000,13000,8000,5333},h)g[406901]=b({e[46057],406901,false,147,336,false,200069,false,"deco/character/weilai",302002,60,1,false,false,false,-22,"1",false,false,false,false,false,false,false,"100,130,1","40,10,1","-50,20,1","40,10,1","-50,20,1",false,"-90,0,1","-40,0,1","-90,0,1","-40,0,1",false,1907,852,386,1044,777,1884,2614,1044,777,1884,1028,"weilai"},h)g[406902]=b({e[11034],406902,1,4,337,"「パラレルワールドって、聞いたことある？\n研究によると、僕たちが何かしらの選択をするたびに、別の世界が誕生するらしいよ。\nだからたまに思うんだ。あの日、ベーカーズをキミにぶつけたのも、ある種の幸運だったんじゃないかって。\n少なくとも、その時に僕達が出会う世界……新たな未来が生まれたってことになるからね。」",200069,1,"deco/character/weilai_0",302002,60,1842,833,392,741,436,2827,2963,741,528,2827,false,false,false,false,false,false,false,false,false,false,false,false,false,"weilai_0"},h)g[406903]=b({e[46057],406903,12,131,338,"「全く、こんな複雑なデザイン、端から一人で着ることを想定してないんだろうね。まぁいいや。僕はキミのためにこれを着たんだから、この後メンテしなきゃいけなくなったら最後まできっちり付き合ってくれよ。」",200069,2,"deco/character/weilai_LF",false,false,1,false,false,false,false,"1",false,false,"-80,0,1",false,"-60,0,1","-60,0,1","-100,0,1",false,false,false,false,false,false,false,false,false,false,false,1956,883,392,1068,714,2063,2510,1068,714,2063,1125,"weilai_lf"},h)g[406904]=b({e[9044],406904,17,71,339,"優雅に踊るヒューマノイドを開発するには、モニタの前でひたすらデータとにらめっこしててもしょうがない。やっぱり、自分で色々なダンスをやってみる必要があると思うんだ。\nほっ……ねえ、ちょっと、足を支えててくれない？ あと少しで、つま先に届く、はず、なんだけ、ど……。\nそう、そんな感じで……！　って、あれ？　なんだか、キミの手のひら、すごく熱くない？",200069,2,"deco/character/weilai_BL",0,false,false,false,false,false,false,false,false,false,false,false,false,"weilai_bl"},h)g[407001]=b({e[25034],407001,false,148,340,false,200070,false,"deco/character/luluxiu",302002,60,1,false,false,false,-160,"1",false,false,false,false,false,false,false,"40,590,0.94",1872,863,388,1507,780,1016,3194,1507,780,1016,1037},h)g[407002]=b({e[24034],407002,1,4,341,false,200070,1,"deco/character/luluxiu_0",302002,60,false,false,1,false,false,false,false,"0,-104,1","0,-88,1",false,"0,-90,1",false,"0,-